const showPreview=()=>{const file=photo.files?.[0];clearPreview();photoNote.textContent='';if(!file)return;if(!validImageFile(file)||file.size>PHOTO_MAX_BYTES){photo.value='';photoNote.textContent='Choose a JPG, PNG, or WebP image up to 5 MB.';return}previewUrl=URL.createObjectURL(file);preview.src=previewUrl;preview.hidden=false;removePhoto.hidden=false;clearStatus()};
