const step=form.querySelector(`[data-guest-step="${eventName}"]`);
step.querySelectorAll('[data-step]').forEach(button=>button.addEventListener('click',()=>{guestCounts[eventName]=Math.max(1,Math.min(10,guestCounts[eventName]+Number(button.dataset.step)));updateEvent(eventName);clearStatus()}));
