function tick(){coverCountdown();const el=$('#cd');if(!el)return;const V=EVS(),i=cur(),now=new Date();let s=Math.max(0,(ist(V[i].s)-now)/1e3);if(isNaN(s))return;document.querySelectorAll('.ec').forEach((c,j)=>c.classList.toggle('on',j==i));const L=$('#cdl');if(now>ist(V[1].e)){L.textContent='Thank you for celebrating with us 🙏';el.innerHTML='';return}if(s==0){L.textContent='The '+V[i].n+' is happening now 🎉';el.innerHTML='';return}L.textContent='Countdown to the '+V[i].n;const v=[['Days',s/86400],['Hours',s%86400/3600],['Minutes',s%3600/60],['Seconds',s%60]];el.innerHTML=v.map(([l,n])=>`<div><b>${String(Math.floor(n)).padStart(2,'0')}</b><span>${l}</span></div>`).join('')}setInterval(tick,1000);
